-- Pharmacy sample database (pharmacy-sample-database) v1 — sqlite
-- Synthetic sample data, CC0-1.0. Deterministic: the same spec and seed produce this byte for byte.
-- seed: flagship:pharmacy-sample-database:1k
-- Engine 2 (faker 10.6.0), locale en_US. UTF-8.
-- Tables in dependency order; foreign keys are added after the data.

BEGIN;

CREATE TABLE "active_ingredients" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "description" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE,
    CONSTRAINT "ck_active_ingredients_description" CHECK ("description" IN ('Small molecule', 'Biologic', 'Vitamin or mineral', 'Hormone')),
    CONSTRAINT "ck_active_ingredients_name" CHECK ("name" IN ('Amoxicillin', 'Ibuprofen', 'Paracetamol', 'Metformin', 'Atorvastatin', 'Omeprazole', 'Lisinopril', 'Amlodipine', 'Simvastatin', 'Levothyroxine', 'Metoprolol', 'Losartan', 'Azithromycin', 'Cetirizine', 'Loratadine', 'Prednisone', 'Sertraline', 'Fluoxetine', 'Gabapentin', 'Hydrochlorothiazide', 'Pantoprazole', 'Montelukast', 'Salbutamol', 'Insulin Glargine', 'Clopidogrel', 'Warfarin', 'Furosemide', 'Ciprofloxacin', 'Doxycycline', 'Naproxen', 'Diclofenac', 'Esomeprazole', 'Rosuvastatin', 'Escitalopram', 'Bupropion', 'Tamsulosin', 'Finasteride', 'Allopurinol', 'Ondansetron', 'Loperamide', 'Famotidine', 'Cholecalciferol', 'Folic Acid', 'Ferrous Sulfate', 'Melatonin', 'Zinc Sulfate', 'Hydrocortisone', 'Clotrimazole', 'Fluticasone', 'Budesonide'))
);

CREATE TABLE "branches" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "address" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "phone" TEXT NOT NULL
);

CREATE TABLE "coupons" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "code" TEXT NOT NULL UNIQUE,
    "discount_percentage" NUMERIC(14,2) NOT NULL,
    "expiry_date" TEXT NOT NULL,
    "is_active" INTEGER NOT NULL,
    "max_discount" NUMERIC(14,2) NOT NULL,
    CONSTRAINT "ck_coupons_discount_percentage" CHECK ("discount_percentage" BETWEEN 5 AND 30),
    CONSTRAINT "ck_coupons_max_discount" CHECK ("max_discount" BETWEEN 5 AND 40)
);

CREATE TABLE "customers" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "address" TEXT NOT NULL,
    "date_of_birth" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "first_name" TEXT NOT NULL,
    "gender" TEXT NOT NULL,
    "last_name" TEXT NOT NULL,
    "phone" TEXT NOT NULL,
    CONSTRAINT "ck_customers_gender" CHECK ("gender" IN ('female', 'male', 'unspecified'))
);

CREATE TABLE "customer_loyalty" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "customer_id" INTEGER NOT NULL UNIQUE,
    "last_updated" TEXT NOT NULL,
    "points_balance" INTEGER NOT NULL,
    "tier" TEXT NOT NULL,
    CONSTRAINT "ck_customer_loyalty_points_balance" CHECK ("points_balance" BETWEEN 0 AND 20000),
    CONSTRAINT "ck_customer_loyalty_tier" CHECK ("tier" IN ('bronze', 'silver', 'gold', 'platinum')),
    FOREIGN KEY ("customer_id") REFERENCES "customers" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "doctors" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "email" TEXT NOT NULL,
    "first_name" TEXT NOT NULL,
    "last_name" TEXT NOT NULL,
    "license_number" TEXT NOT NULL UNIQUE,
    "phone" TEXT NOT NULL,
    "specialty" TEXT NOT NULL,
    CONSTRAINT "ck_doctors_specialty" CHECK ("specialty" IN ('general_practice', 'internal_medicine', 'pediatrics', 'cardiology', 'dermatology', 'psychiatry', 'endocrinology', 'orthopedics'))
);

CREATE TABLE "dosage_forms" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "description" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE,
    CONSTRAINT "ck_dosage_forms_description" CHECK ("description" IN ('Taken by mouth', 'Applied to the skin', 'Given by a clinician', 'Inhaled', 'Used in the eye or ear')),
    CONSTRAINT "ck_dosage_forms_name" CHECK ("name" IN ('tablet', 'capsule', 'syrup', 'cream', 'injection', 'inhaler', 'drops', 'patch'))
);

CREATE TABLE "insurance_providers" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "address" TEXT NOT NULL,
    "contact_person" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "phone" TEXT NOT NULL
);

CREATE TABLE "manufacturers" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "address" TEXT NOT NULL,
    "contact_person" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "phone" TEXT NOT NULL
);

CREATE TABLE "medicine_categories" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "description" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE,
    CONSTRAINT "ck_medicine_categories_description" CHECK ("description" IN ('Prescription only', 'Over the counter', 'Mixed: some lines need a prescription')),
    CONSTRAINT "ck_medicine_categories_name" CHECK ("name" IN ('analgesics', 'antibiotics', 'antihistamines', 'antihypertensives', 'antidepressants', 'antidiabetics', 'cardiovascular', 'gastrointestinal', 'respiratory', 'dermatology', 'vitamins_and_supplements', 'hormones'))
);

CREATE TABLE "packaging_types" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "description" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE,
    CONSTRAINT "ck_packaging_types_description" CHECK ("description" IN ('Child-resistant', 'Tamper-evident seal', 'Keep refrigerated', 'Single use')),
    CONSTRAINT "ck_packaging_types_name" CHECK ("name" IN ('blister_pack', 'bottle', 'tube', 'vial', 'box', 'sachet'))
);

CREATE TABLE "medicines" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "category_id" INTEGER NOT NULL,
    "dosage_form_id" INTEGER NOT NULL,
    "manufacturer_id" INTEGER NOT NULL,
    "name" TEXT NOT NULL,
    "packaging_type_id" INTEGER NOT NULL,
    "price" NUMERIC(14,2) NOT NULL,
    "requires_prescription" INTEGER NOT NULL,
    "scientific_name" TEXT NOT NULL,
    "sku" TEXT NOT NULL UNIQUE,
    "strength" TEXT NOT NULL,
    CONSTRAINT "ck_medicines_name" CHECK ("name" IN ('Amoxicillin', 'Ibuprofen', 'Paracetamol', 'Metformin', 'Atorvastatin', 'Omeprazole', 'Lisinopril', 'Amlodipine', 'Simvastatin', 'Levothyroxine', 'Metoprolol', 'Losartan', 'Azithromycin', 'Cetirizine', 'Loratadine', 'Prednisone', 'Sertraline', 'Fluoxetine', 'Gabapentin', 'Hydrochlorothiazide', 'Pantoprazole', 'Montelukast', 'Salbutamol', 'Insulin Glargine', 'Clopidogrel', 'Warfarin', 'Furosemide', 'Ciprofloxacin', 'Doxycycline', 'Naproxen', 'Diclofenac', 'Esomeprazole', 'Rosuvastatin', 'Escitalopram', 'Bupropion', 'Tamsulosin', 'Finasteride', 'Allopurinol', 'Ondansetron', 'Loperamide', 'Famotidine', 'Cholecalciferol', 'Folic Acid', 'Ferrous Sulfate', 'Melatonin', 'Zinc Sulfate', 'Hydrocortisone', 'Clotrimazole', 'Fluticasone', 'Budesonide')),
    CONSTRAINT "ck_medicines_price" CHECK ("price" BETWEEN 2 AND 95),
    CONSTRAINT "ck_medicines_strength" CHECK ("strength" IN ('5 mg', '10 mg', '20 mg', '40 mg', '100 mg', '250 mg', '500 mg', '1 g', '5 mg/ml', '1%')),
    FOREIGN KEY ("category_id") REFERENCES "medicine_categories" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("dosage_form_id") REFERENCES "dosage_forms" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("manufacturer_id") REFERENCES "manufacturers" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("packaging_type_id") REFERENCES "packaging_types" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "medicine_ingredients" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "ingredient_id" INTEGER NOT NULL,
    "medicine_id" INTEGER NOT NULL,
    "strength" TEXT NOT NULL,
    CONSTRAINT "ck_medicine_ingredients_strength" CHECK ("strength" IN ('5 mg', '10 mg', '20 mg', '50 mg', '100 mg', '250 mg', '500 mg')),
    FOREIGN KEY ("ingredient_id") REFERENCES "active_ingredients" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("medicine_id") REFERENCES "medicines" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "payment_methods" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "description" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE,
    CONSTRAINT "ck_payment_methods_description" CHECK ("description" IN ('Settled at the till', 'Settled by the insurer', 'Prepaid')),
    CONSTRAINT "ck_payment_methods_name" CHECK ("name" IN ('card', 'cash', 'mobile_wallet', 'insurance_direct', 'gift_card'))
);

CREATE TABLE "prescriptions" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "customer_id" INTEGER NOT NULL,
    "doctor_id" INTEGER NOT NULL,
    "expiry_date" TEXT NOT NULL,
    "issue_date" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    CONSTRAINT "ck_prescriptions_status" CHECK ("status" IN ('dispensed', 'partially_dispensed', 'expired', 'cancelled')),
    FOREIGN KEY ("customer_id") REFERENCES "customers" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("doctor_id") REFERENCES "doctors" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "prescription_items" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "dispensed_quantity" INTEGER NOT NULL,
    "dosage_instruction" TEXT NOT NULL,
    "medicine_id" INTEGER NOT NULL,
    "prescribed_quantity" INTEGER NOT NULL,
    "prescription_id" INTEGER NOT NULL,
    CONSTRAINT "ck_prescription_items_dosage_instruction" CHECK ("dosage_instruction" IN ('One tablet daily', 'One tablet twice daily', 'One tablet three times daily', 'Two tablets at night', 'Apply thinly twice daily', 'Two puffs when needed', '5 ml every eight hours', 'As directed')),
    CONSTRAINT "ck_prescription_items_prescribed_quantity" CHECK ("prescribed_quantity" BETWEEN 1 AND 90),
    FOREIGN KEY ("medicine_id") REFERENCES "medicines" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("prescription_id") REFERENCES "prescriptions" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "roles" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "description" TEXT NOT NULL,
    "name" TEXT NOT NULL UNIQUE,
    CONSTRAINT "ck_roles_description" CHECK ("description" IN ('Dispenses prescriptions', 'Works the till', 'Orders stock', 'Runs a branch', 'Manages the system')),
    CONSTRAINT "ck_roles_name" CHECK ("name" IN ('pharmacist', 'technician', 'cashier', 'branch_manager', 'buyer', 'admin'))
);

CREATE TABLE "shelves" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "branch_id" INTEGER NOT NULL,
    "code" TEXT NOT NULL,
    "location_description" TEXT NOT NULL,
    CONSTRAINT "ck_shelves_location_description" CHECK ("location_description" IN ('Behind the counter', 'Front of store', 'Cold storage', 'Controlled drugs cabinet', 'Back room', 'Self-service aisle')),
    FOREIGN KEY ("branch_id") REFERENCES "branches" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "inventory_stocks" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "batch_number" TEXT NOT NULL,
    "branch_id" INTEGER NOT NULL,
    "expiry_date" TEXT NOT NULL,
    "medicine_id" INTEGER NOT NULL,
    "quantity" INTEGER NOT NULL,
    "shelf_id" INTEGER NOT NULL,
    CONSTRAINT "ck_inventory_stocks_quantity" CHECK ("quantity" BETWEEN 0 AND 400),
    FOREIGN KEY ("branch_id") REFERENCES "branches" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("medicine_id") REFERENCES "medicines" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("shelf_id") REFERENCES "shelves" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "suppliers" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "address" TEXT NOT NULL,
    "contact_name" TEXT NOT NULL,
    "email" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "phone" TEXT NOT NULL
);

CREATE TABLE "purchase_orders" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "branch_id" INTEGER NOT NULL,
    "delivery_date" TEXT NOT NULL,
    "order_date" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    "supplier_id" INTEGER NOT NULL,
    "total_amount" NUMERIC(14,2) NOT NULL,
    CONSTRAINT "ck_purchase_orders_status" CHECK ("status" IN ('received', 'partially_received', 'ordered', 'cancelled')),
    CONSTRAINT "ck_purchase_orders_total_amount" CHECK ("total_amount" BETWEEN 1 AND 10000),
    FOREIGN KEY ("branch_id") REFERENCES "branches" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("supplier_id") REFERENCES "suppliers" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "purchase_order_items" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "medicine_id" INTEGER NOT NULL,
    "purchase_order_id" INTEGER NOT NULL,
    "quantity_ordered" INTEGER NOT NULL,
    "quantity_received" INTEGER NOT NULL,
    "unit_cost" NUMERIC(14,2) NOT NULL,
    CONSTRAINT "ck_purchase_order_items_quantity_ordered" CHECK ("quantity_ordered" BETWEEN 10 AND 500),
    CONSTRAINT "ck_purchase_order_items_unit_cost" CHECK ("unit_cost" BETWEEN 1 AND 120),
    FOREIGN KEY ("medicine_id") REFERENCES "medicines" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("purchase_order_id") REFERENCES "purchase_orders" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "supplier_invoices" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "due_date" TEXT NOT NULL,
    "invoice_date" TEXT NOT NULL,
    "invoice_number" TEXT NOT NULL UNIQUE,
    "paid_amount" NUMERIC(14,2),
    "purchase_order_id" INTEGER NOT NULL UNIQUE,
    "status" TEXT NOT NULL,
    "total_amount" NUMERIC(14,2) NOT NULL,
    CONSTRAINT "ck_supplier_invoices_status" CHECK ("status" IN ('paid', 'unpaid', 'overdue')),
    FOREIGN KEY ("purchase_order_id") REFERENCES "purchase_orders" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "users" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "email" TEXT NOT NULL UNIQUE,
    "is_active" INTEGER NOT NULL,
    "password_hash" TEXT NOT NULL,
    "username" TEXT NOT NULL UNIQUE
);

CREATE TABLE "employees" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "branch_id" INTEGER NOT NULL,
    "first_name" TEXT NOT NULL,
    "hire_date" TEXT NOT NULL,
    "last_name" TEXT NOT NULL,
    "license_number" TEXT NOT NULL UNIQUE,
    "user_id" INTEGER NOT NULL UNIQUE,
    FOREIGN KEY ("branch_id") REFERENCES "branches" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "sales" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "branch_id" INTEGER NOT NULL,
    "customer_id" INTEGER NOT NULL,
    "discount_amount" NUMERIC(14,2) NOT NULL,
    "employee_id" INTEGER NOT NULL,
    "net_amount" NUMERIC(14,2) NOT NULL,
    "sale_date" TEXT NOT NULL,
    "tax_amount" NUMERIC(14,2) NOT NULL,
    "total_amount" NUMERIC(14,2) NOT NULL,
    FOREIGN KEY ("branch_id") REFERENCES "branches" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("customer_id") REFERENCES "customers" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("employee_id") REFERENCES "employees" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "coupon_usages" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "coupon_id" INTEGER NOT NULL,
    "discount_applied" NUMERIC(14,2) NOT NULL,
    "sale_id" INTEGER NOT NULL UNIQUE,
    CONSTRAINT "ck_coupon_usages_discount_applied" CHECK ("discount_applied" BETWEEN 1 AND 12),
    FOREIGN KEY ("coupon_id") REFERENCES "coupons" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("sale_id") REFERENCES "sales" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "delivery_details" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "actual_delivery" TEXT,
    "delivery_address" TEXT NOT NULL,
    "estimated_delivery" TEXT NOT NULL,
    "recipient_name" TEXT NOT NULL,
    "recipient_phone" TEXT NOT NULL,
    "sale_id" INTEGER NOT NULL UNIQUE,
    "status" TEXT NOT NULL,
    CONSTRAINT "ck_delivery_details_status" CHECK ("status" IN ('delivered', 'out_for_delivery', 'failed', 'cancelled')),
    FOREIGN KEY ("sale_id") REFERENCES "sales" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "insurance_claims" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "approved_amount" NUMERIC(14,2),
    "claim_amount" NUMERIC(14,2) NOT NULL,
    "insurance_provider_id" INTEGER NOT NULL,
    "policy_number" TEXT NOT NULL,
    "sale_id" INTEGER NOT NULL UNIQUE,
    "status" TEXT NOT NULL,
    "submission_date" TEXT NOT NULL,
    CONSTRAINT "ck_insurance_claims_status" CHECK ("status" IN ('approved', 'partially_approved', 'denied', 'pending')),
    FOREIGN KEY ("insurance_provider_id") REFERENCES "insurance_providers" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("sale_id") REFERENCES "sales" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "payments" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "amount" NUMERIC(14,2) NOT NULL,
    "payment_date" TEXT NOT NULL,
    "payment_method_id" INTEGER NOT NULL,
    "sale_id" INTEGER NOT NULL UNIQUE,
    "transaction_reference" TEXT NOT NULL UNIQUE,
    FOREIGN KEY ("payment_method_id") REFERENCES "payment_methods" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("sale_id") REFERENCES "sales" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "returns" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "employee_id" INTEGER NOT NULL,
    "reason" TEXT NOT NULL,
    "return_date" TEXT NOT NULL,
    "sale_id" INTEGER NOT NULL UNIQUE,
    "total_refund_amount" NUMERIC(14,2) NOT NULL,
    CONSTRAINT "ck_returns_reason" CHECK ("reason" IN ('Wrong medicine dispensed', 'Customer changed their mind', 'Packaging damaged', 'Prescription changed by the doctor', 'Allergic reaction reported')),
    FOREIGN KEY ("employee_id") REFERENCES "employees" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("sale_id") REFERENCES "sales" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "return_items" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "medicine_id" INTEGER NOT NULL,
    "quantity" INTEGER NOT NULL,
    "refund_amount" NUMERIC(14,2) NOT NULL,
    "return_id" INTEGER NOT NULL,
    CONSTRAINT "ck_return_items_quantity" CHECK ("quantity" BETWEEN 1 AND 3),
    FOREIGN KEY ("medicine_id") REFERENCES "medicines" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("return_id") REFERENCES "returns" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "sale_items" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "discount_amount" INTEGER NOT NULL,
    "medicine_id" INTEGER NOT NULL,
    "quantity" INTEGER NOT NULL,
    "sale_id" INTEGER NOT NULL,
    "total_price" NUMERIC(14,2) NOT NULL,
    "unit_price" NUMERIC(14,2) NOT NULL,
    CONSTRAINT "ck_sale_items_quantity" CHECK ("quantity" BETWEEN 1 AND 3),
    FOREIGN KEY ("medicine_id") REFERENCES "medicines" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("sale_id") REFERENCES "sales" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "shifts" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "cash_float_end" NUMERIC(14,2) NOT NULL,
    "cash_float_start" NUMERIC(14,2) NOT NULL,
    "employee_id" INTEGER NOT NULL,
    "end_time" TEXT NOT NULL,
    "start_time" TEXT NOT NULL,
    "status" TEXT NOT NULL,
    CONSTRAINT "ck_shifts_cash_float_end" CHECK ("cash_float_end" BETWEEN 100 AND 4000),
    CONSTRAINT "ck_shifts_cash_float_start" CHECK ("cash_float_start" BETWEEN 100 AND 300),
    CONSTRAINT "ck_shifts_status" CHECK ("status" IN ('closed', 'open', 'reconciled')),
    FOREIGN KEY ("employee_id") REFERENCES "employees" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "stock_adjustments" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "adjustment_date" TEXT NOT NULL,
    "adjustment_type" TEXT NOT NULL,
    "employee_id" INTEGER NOT NULL,
    "inventory_stock_id" INTEGER NOT NULL,
    "quantity_adjusted" INTEGER NOT NULL,
    "reason" TEXT NOT NULL,
    CONSTRAINT "ck_stock_adjustments_adjustment_type" CHECK ("adjustment_type" IN ('count_correction', 'damaged', 'expired', 'transfer_in', 'transfer_out', 'recall')),
    CONSTRAINT "ck_stock_adjustments_quantity_adjusted" CHECK ("quantity_adjusted" BETWEEN 1 AND 120),
    CONSTRAINT "ck_stock_adjustments_reason" CHECK ("reason" IN ('Shelf count did not match the system', 'Box crushed in delivery', 'Past its expiry date', 'Moved between branches', 'Withdrawn by the manufacturer')),
    FOREIGN KEY ("employee_id") REFERENCES "employees" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("inventory_stock_id") REFERENCES "inventory_stocks" ("id") DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE "user_roles" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT,
    "role_id" INTEGER NOT NULL,
    "user_id" INTEGER NOT NULL,
    FOREIGN KEY ("role_id") REFERENCES "roles" ("id") DEFERRABLE INITIALLY DEFERRED,
    FOREIGN KEY ("user_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY DEFERRED
);

